    "Cada año deja una huella. Elige dónde poner tu energía.": "每一年都会留下痕迹。选择把你的精力放在哪里。",
    "Cada aportación parecía pequeña. Con los años, el hábito se convirtió en una colchón que no esperabas.": "每一项贡献都显得微不足道。多年来，这个习惯变成了你意想不到的缓冲垫。",
    "Cada caída es una razón para volver a empezar.": "每一次跌倒都是重新开始的理由。",
    "Cada categoría se normaliza a 0–100. La puntuación total aplica estos pesos y después una puerta de bienestar: si salud o felicidad son muy bajas, el resultado se reduce hasta un 25 %. La longevidad se compara con la esperanza de vida del país y no recompensa vivir más por una ventaja demográfica.": "每个类别均标准化为 0-100。总分应用这些权重，然后应用幸福门：如果健康或幸福感非常低，结果最多会降低 25%。长寿是与国家的预期寿命进行比较的，并不意味着寿命更长就可以获得人口优势。",
    "Cada destino tiene costes, idioma y reglas de visado distintas. La información importa más que la ilusión.": "每个目的地都有不同的费用、语言和签证规则。信息比幻觉更重要。",
    "Cada empleado cambia tus costes fijos, tu reputación y tu responsabilidad.": "每个员工都会改变你的固定成本、你的声誉和你的责任。",
    "Cada envío cuesta más, pero depender de un único cliente y enviar producto defectuoso resulta menos probable.": "每次发货的成本更高，但依赖单个客户并运输有缺陷的产品的可能性较小。",
    "Cada pago se valida en el servidor y queda registrado en el banco. Importes en dólares PPP.": "每笔付款都会在服务器上进行验证并在银行中注册。金额以购买力平价美元计算。",
