    "Cambiaste de destino. El nuevo proceso era más lento, pero encajaba mejor con tu perfil. La migración dejó de ser un solo billete.": "你改变了你的目的地。新流程速度较慢，但​​更适合您的个人资料。移民不再只是一张门票。",
    "Cambiaste de profesor y tardaste semanas en acostumbrarte a su voz.": "你换了老师，花了几周的时间才适应他的声音。",
    "Cambiaste el aula por un turno. Ganaste tu primer dinero real y perdiste algunas tardes que no volverán.": "你换了教室换班。你赢得了第一笔真金白银，但也失去了一些无法挽回的下午。",
    "Cambiaste horarios y habitaciones. Hubo días de agotamiento y días en los que entendiste a tus padres de una forma nueva.": "您更改了时间表和房间。 There were days of exhaustion and days when you understood your parents in a new way.",
    "Cambiasteis la prisa por un plan de idioma, trabajo y trámites. La espera tuvo una dirección.": "你改变了对语言、工作和文书工作计划的匆忙。等待是有方向的。",
