    "Cerraste el negocio. Las deudas no desaparecieron y la reputación quedó marcada, pero dejaste de acumular pérdidas cada mes.": "你关门了。债务并没有消失，名誉也没有受到伤害，但你不再每个月都在积累损失。",
    "Cerraste la carta del banco y seguiste con tu presupuesto. No era la opción emocionante, pero dormiste mejor.": "您关闭了银行的信件并继续制定预算。这不是一个令人兴奋的选择，但你睡得更好了。",
    "Cerraste unos días, corregiste lo urgente y reabriste con el expediente en orden. La caja perdió margen; la licencia siguió viva.": "你关闭了几天，纠正了紧急的事情，然后按顺序重新打开了文件。箱体损失余量；该许可证仍然有效。",
