    "China: población, nacimientos, urbanización y desempleo urbano 2024 (NBS); mortalidad infantil 2024 (NHC); PIB PPP 2024 (WDI/UNdata, redondeado). Esperanza de vida por sexo: referencia censal 2020 (80,88 / 75,37), no dato 2024. Gini, escolaridad, fecundidad y parámetros derivados: aproximaciones de juego provisionales.": "中国：2024年人口、出生率、城镇化和城镇失业（国家统计局）； 2024 年婴儿死亡率 (NHC)； 2024 年 GDP 购买力平价（WDI/UNdata，四舍五入）。按性别划分的预期寿命：2020 年人口普查参考值 (80.88 / 75.37)，2024 年无数据。基尼系数、受教育程度、生育率和派生参数：临时博弈近似值。",
