    "Clases, ensayos y escenarios pequeños. Ya habías mostrado interés; ahora toca tomarse en serio el oficio.": "上课、排练和小舞台。你已经表现出了兴趣；现在是认真对待这项工作的时候了。",
    "Clases, grabaciones y un local pequeño. Tu formación musical por fin tiene una puerta propia.": "课程、录音和一个小场地。你的音乐训练终于有了自己的大门。",
