    "Coste inicial de mediación y mudanza. Se abre una secuencia para negociar patrimonio, vivienda y obligaciones de cuidado. El presupuesto deja de sumar el ingreso de tu pareja.": "调解和搬家的初始费用。接下来将开始协商资产、住房和护理义务。预算不再增加您伴侣的收入。",
    "Coste inicial mayor y espera de tres meses. La documentación mejora la posición del caso simulado, sin garantizar el resultado.": "较高的初始成本和三个月的等待。文档改善了模拟案例的位置，但不保证结果。",
    "Costes": "成本",
    "Costes adicionales. La valoración del modelo puede aumentar o reducir la compensación; preparar pruebas ayuda, pero no garantiza ventaja.": "额外费用。模型估值可能会增加或减少报酬；准备测试有帮助，但并不能保证优势。",
    "Costes previsibles": "可预测的成本",
    "Costes y dificultad de visado son parámetros orientativos. La vida en destino depende de tus estudios, idioma y decisiones posteriores.": "签证费用和难度是指示性参数。目的地的生活取决于您的学习、语言和随后的决定。",
    "Crear empresa tecnológica": "创建科技公司",
