    "Crecer más despacio con clientes que ya conocen tu trabajo.": "与已经了解您工作的客户一起成长得更慢。",
    "Crecer no es solo vender más: también es asumir alquileres, personal y una estructura más difícil de deshacer.": "增长不仅仅意味着销售更多：它还意味着承担租金、员工和更难以撤销的结构。",
    "Creció bajo tutela familiar": "他是在家人的监护下长大的",
    "Creciste entre manos conocidas y habitaciones pequeñas llenas de voces. Aprendiste pronto que pedir ayuda no era un problema.": "你在熟悉的双手和充满声音的小房间里长大。您很早就知道寻求帮助不是问题。",
    "Creciste entre recursos, viajes y expectativas altas. La abundancia también tiene sus propias reglas y silencios.": "你是在资源、旅行和高期望中长大的。丰富也有它自己的规则和沉默。",
