    "Cruzaste con ayuda de una red de conocidos. El trabajo llegó pronto; el miedo a no tener papeles tardó mucho más en irse.": "You crossed with the help of a network of acquaintances.工作很快就来了； The fear of not having papers took much longer to go away.",
    "Cuando el mundo empiece a moverse y tomes la primera decisión, esta página se llenará sola.": "当世界开始变化并且您做出第一个决定时，此页面将自动填充。",
