    "Cubrirse las espaldas": "遮住你的背部",
    "Cubriste agujeros y volviste a colgar un cuadro torcido. La casa recuperó su forma y tú recuperaste una rutina.": "你盖住了洞，重新挂了一张歪歪扭扭的图画。房子恢复了原样，你也恢复了日常生活。",
    "Cuentas del último cierre anual. Cada empresa conserva sus gastos, equipo y riesgos.": "上次年度结算的账目。每家公司保留其费用、设备和风险。",
