    "Cuidado de la mascota": "宠物护理",
    "Cuidado de la salud": "卫生保健",
    "Cuidado médico reforzado": "加强医疗护理",
    "Cuidados básicos y seguimiento": "基本护理和随访",
    "Cuidados diarios y compañía, con un coste elevado.": "日常的照顾和陪伴，成本很高。",
    "Cuidar a alguien que aún no existe": "照顾一个还不存在的人",
    "Cuidar a un familiar enfermo": "照顾生病的家庭成员",
    "Cuidar de otros": "关心他人",
    "Cuidar de quien te cuidó": "照顾那些照顾你的人",
    "Cuidar durante una crisis": "危机期间的关怀",
    "Cuidar el cuerpo": "照顾好身体",
    "Cuidar el vínculo familiar sin entregar a otros el control de tu vida afectiva.": "照顾好家庭纽带，不要让别人控制你的情感生活。",
    "Cuidar el vínculo sin convertirlo en una cita.": "请妥善保管链接，不要将其变成日期。",
    "Cuidar en casa": "在家照顾",
    "Cuidar la confianza sin mezclar salario, evaluación y afecto.": "照顾好信任，不要把薪酬、评价、感情混为一谈。",
    "Cuidar primero tu casa y tu salud mental antes de asumir otra carga.": "在承担其他负担之前，先照顾好你的家庭和心理健康。",
    "Cuidar sin desaparecer": "关怀而不消失",
    "Cuidar una amistad internacional": "关爱国际友谊",
    "Cuidar, conectar o insistir sin prisa.": "关心、联系或坚持，但不要着急。",
    "Cuidarles en casa": "在家照顾他们",
