    "Entrar en un taller de diseño": "进入设计工作室",
    "Entraste en medicina. Los primeros años fueron una mezcla de vocación, cansancio y libros que nunca terminaban.": "你进入医学界。最初的几年是职业、疲劳和永无休止的书籍的混合体。",
    "Entraste en un trabajo que no elegiste. Te dio ingresos y una rutina, y también una rabia que tardó en irse.": "你进入了一份并非你选择的工作。它给你带来了收入和日常生活，也带来了需要时间才能消退的愤怒。",
    "Entre 2 y 18 caracteres": "2 到 18 个字符之间",
    "Entre ejercicios y errores compartidos, una persona empieza a buscarte en los descansos. No sabes si es amistad o algo más.": "在练习和共同犯错之间，一个人开始在休息时寻找你。你不知道这是友谊还是其他什么。",
    "Entre trabajo, facturas y cuidados queda poco tiempo. ¿Qué quieres proteger durante los próximos años?": "在工作、账单和护理之间，剩下的时间所剩无几。未来几年你想保护什么？",
    "Entre turnos aprendiste un oficio con las manos. No era el futuro que imaginabas, pero empezaste a ganar algo tuyo.": "在轮班之间，你学会了用手做生意。这不是你想象的未来，但你开始收获一些属于自己的东西。",
    "Entrega sin retraso.": "交货毫不拖延。",
    "Entregar todo y regularizar lo que falte": "提供一切并规范缺少的内容",
    "Entrenamientos, equipo y barro. Hay una cuota que la familia debe asumir.": "培训、设备和泥浆。家庭必须承担一定的费用。",
    "Entrenar para una excursión": "训练去旅行",
    "Entrenar, competir y pertenecer a un grupo con un objetivo común.": "训练、竞争并加入一个有着共同目标的团队。",
    "Envejecer en familia": "一家人一起变老",
    "Enviaste currículums sin decírselo a nadie. La entrevista salió bien y cambiaste de aires con una mezcla de miedo y alivio.": "你在没有告诉任何人的情况下发出了简历。面试进行得很顺利，你带着恐惧和宽慰的心情改变了态度。",
    "Enviaste otra solicitud y recibiste el silencio habitual. Aun así, seguiste revisando ofertas.": "你又发出了一个请求，但得到的却是一如既往的沉默。尽管如此，您还是继续查看报价。",
    "Enviaste solicitudes y acudiste a entrevistas. Aún no hubo una oferta; puedes seguir intentándolo el próximo mes.": "您提交了申请并参加了面试。还没有报价；下个月你可以继续尝试。",
    "Enviaste una ayuda estable. No resolvió todos sus problemas, pero les permitió afrontar el mes con menos miedo. Tú también aprendiste a poner una cifra a la responsabilidad.": "你送来了稳定的帮助。它并没有解决他们所有的问题，但它让他们能够以更少的恐惧来面对这个月。你还学会了如何衡量责任。",
