    "Esta operación se abre al cumplir 18 años. Durante la infancia puedes cuidarte, aprender, compartir tiempo y adoptar un animal con el presupuesto familiar.": "当您年满 18 岁时，这项手术就会开始。在童年时期，您可以照顾自己、学习、分享时间并用家庭预算收养动物。",
