    "Este catálogo muestra programas de tu país de residencia. Para estudiar fuera, primero compara admisión, viaje, documentación y dinero para vivir. Mudarte no te concede un título ni una matrícula.": "该目录显示您居住国家/地区的节目。出国留学，首先要比较入学、旅行、证件和生活费用。搬家并不会给你学位或学费。",
