    "Horarios firmes y poca improvisación. La disciplina se instala antes que la ternura.": "日程安排严格，很少有即兴创作。纪律先于温柔。",
    "Horas adicionales, un segundo trabajo o un pequeño servicio.": "加班、第二份工作或小型服务。",
    "Horas extra o un proyecto personal. Más ingresos, menos descanso.": "加班或个人项目。收入增加，休息减少。",
    "Hoy": "今天",
    "Hubo citas olvidables y mensajes sin respuesta. Aprendiste a distinguir soledad de desesperación.": "有令人忘记的约会和未回复的消息。你学会了区分孤独和绝望。",
    "Hubo días corrientes, decisiones difíciles y momentos que hicieron que esta vida fuera tuya. Su valor también está en las personas que acompañaste y en lo que aprendiste al seguir adelante.": "那些平凡的日子、艰难的决定和时刻让你的生活变得美好。它的价值也在于你陪伴的人以及你在前进过程中学到的东西。",
    "Hubo gratitud, sin discurso ni ocasión especial.": "有感激之情，无需言语或特殊场合。",
    "Hubo un día en que la ausencia de alguien se notó en una costumbre pequeña.": "有一天，在一个小习俗中发现有人缺席。",
    "Hubo un momento del día en que todo pareció estar en su sitio, aunque nada hubiera cambiado.": "有一天的某个时刻，一切似乎都在原地踏步，尽管一切都没有改变。",
    "Hubo una mesa larga y personas de etapas distintas. No todo fue perfecto, pero decidisteis seguir construyendo juntos.": "那里有一张长桌，还有不同阶段的人。并非一切都是完美的，但你们决定继续共同建设。",
