    "Igualaste el precio y conservaste clientes. Vendiste más, pero cada venta dejó menos dinero y el equipo trabajó al límite.": "您匹配了价格并留住了客户。你卖出了更多的东西，但每次销售留下的钱却更少了，团队的工作已经到了极限。",
