    "Iniciar la reagrupación": "开始重组",
    "Iniciar un proyecto de crianza con nueve meses de preparación en el modo mensual; no es una compra de puntos.": "以月度模式启动9个月准备的育种项目；这不是积分购买。",
    "Iniciaste economía y gestión en Bocconi. El nombre de la universidad no sustituye la experiencia ni asegura un empleo.": "您在博科尼开始学习经济学和管理学。大学名称不能取代经验或保证就业。",
    "Iniciaste un plan de recuperación: la deuda se redujo un 30 %, con un coste para tu historial. El resto requiere ingresos y disciplina.": "你开始了一项恢复计划：债务减少了 30%，但代价是你的历史。其余的需要收入和纪律。",
    "Iniciasteis un proyecto de crianza. Reservasteis dinero y hablasteis de cómo repartir el cuidado antes de la llegada.": "你开始了一个育儿项目。你们在抵达前预留了钱并讨论了如何分担护理。",
    "Inicio más lento, seguimiento y experiencia verificable.": "起步较慢，后续可验证的经验。",
    "Inmovilizar caja a cambio de precio y disponibilidad.": "固定现金以换取价格和可用性。",
