    "Intentar una relación": "尝试建立关系",
    "Intentaste ayudar y terminaste agotado. La gratitud ajena no siempre compensó el cansancio.": "你试图提供帮助，但最终却筋疲力尽。他人的感激之情并不总能弥补疲劳。",
    "Intentasteis algo más y no encajó. La amistad quedó herida, aunque ninguno había mentido.": "您尝试了其他方法，但没有成功。尽管两人都没有撒谎，但友谊还是受到了伤害。",
