    "Inventar una regla para el juego": "制定游戏规则",
    "Inventaste un juego con tus vecinos. Nadie se ponía de acuerdo sobre las reglas.": "你和你的邻居发明了一种游戏。没有人同意这些规则。",
    "Invertir en catálogo y atención posventa. Debes sostener garantías, devoluciones y reposición.": "投资目录和售后服务。您必须维持保证、退货和换货。",
    "Invertir en el espacio sin cambiar de barrio.": "在不改变社区的情况下投资空间。",
    "Invertir en el producto y en los clientes que ya tienes, sin abrir otro frente.": "投资于您已有的产品和客户，而无需开辟另一条战线。",
    "Invertir en formación": "投资培训",
    "Invertir en inspección y compradores alternativos": "投资于检验和替代买家",
