    "Invertir en muestras y preparación comercial. Después elegirás mercado y condiciones; todavía no existe un pedido comprometido.": "投资样品和商业准备。然后您将选择市场和条件；目前还没有承诺的订单。",
    "Invertir en obra, stock y personal; asumir el riesgo completo.": "投资工作、库存和人员；承担全部风险。",
