    "Mayor capacidad y costes salariales permanentes; una mala previsión de demanda puede crear pérdidas.": "更大的能力和永久性的工资成本；需求预测不佳可能会造成损失。",
    "Mayor rentabilidad suele significar más riesgo. Mantener liquidez también es una decisión financiera.": "更高的盈利能力通常意味着更高的风险。保持流动性也是一项财务决策。",
