    "Medir coste por ración y reducir mermas antes de cambiar precios": "在改变价格之前衡量每份服务的成本并减少浪费",
    "Medir margen y rotación antes de reponer": "补货前测量边际和周转",
    "Mejor resultado ·": "最好的结果·",
    "Mejora parcial y menor gasto inicial. Quedarán trabajos para después.": "部分改进并降低初始费用。以后还会有工作的。",
    "Mejorar tu casa actual": "改善你现在的房子",
    "Menor complejidad logística; conservas la posibilidad de exportar después.": "降低物流复杂性；您保留稍后导出的可能性。",
    "Menor preparación inicial; la revisión posterior puede incrementar costes o compensación.": "前期准备工作较少；后续审查可能会增加成本或补偿。",
    "Menos actividades y expectativas, sin una compra nueva.": "活动和期望减少，无需进行新购买。",
    "Menos cambio y menos coste de instalación; crecimiento profesional gradual.": "改动少，安装成本低；逐步的专业成长。",
    "Menos capital, menos promesas y la experiencia de la caída.": "资本少了，承诺少了，跌倒的经历也少了。",
    "Menos capital, menos promesas y un riesgo medido.": "更少的资本、更少的承诺和可衡量的风险。",
    "Menos coste y más compañía, pero menos intimidad.": "成本更低，陪伴更多，但隐私更少。",
    "Menos esperas y más acceso. La prima mensual se nota.": "更少的等待和更多的访问。每月的保费是显而易见的。",
    "Menos exposición al impago, aunque negociar lleva tiempo y puede reducir el tamaño del pedido.": "尽管谈判需要时间并且可能会减少订单规模，但未付款的风险较小。",
    "Menos gastos y más vida social, con menos intimidad.": "更少的开支和更多的社交生活，但隐私更少。",
    "Menos ingreso inmediato; cada ampliación requiere presupuesto y aprobación por escrito.": "直接收入减少；每次扩建都需要预算和书面批准。",
    "Menos ingresos durante esta etapa; proteger calidad y evitar una expansión sin caja.": "此阶段收入较少；保护质量并避免无盒扩展。",
    "Menos inversión y más flexibilidad, pero también menos estructura.": "投资更少，灵活性更大，但结构也更少。",
    "Menos margen para crecer, más posibilidades de sobrevivir.": "成长空间更小，生存机会更多。",
    "Menos obligaciones y más espacio sin pantallas.": "更少的义务和更多没有屏幕的空间。",
    "Menos protagonismo, pero una red sostenible.": "不太显眼，但却是一个可持续的网络。",
    "Menos rentabilidad, más previsibilidad. El dinero queda atado un tiempo.": "盈利能力较低，可预测性较高。钱暂时被困住了。",
    "Menos ruido y un equilibrio más amable.": "噪音更少，平衡更友好。",
    "Menos sueldo y más vida. Recuperas tardes que llevabas años cediendo.": "工资少了，生活多了。你可以恢复多年来一直放弃的下午时光。",
    "Menos tiempo de estudio, más responsabilidad. La familia lo nota.": "更少的学习时间，更多的责任。家人注意到了这一点。",
    "Menos variedad y facturación potencial, con una operación más sencilla.": "品种和潜在营业额更少，操作更简单。",
    "Menos vértigo, menos capital y más control. El crecimiento tendrá que esperar.": "更少的眩晕，更少的资本，更多的控制。增长必须等待。",
