    "Modelo de mortalidad paramétrico de LIFE DUEL. NO es una tabla de mortalidad oficial. La esperanza de vida al nacer y la mortalidad infantil por país provienen de Naciones Unidas / UN IGME; el resto son parámetros de simulación calibrados para reproducir una longevidad plausible y permitir que los hábitos y las decisiones influyan.": "LIFE DUEL 参数死亡率模型。这不是官方死亡率表。按国家划分的出生预期寿命和婴儿死亡率来自联合国/联合国 IGME；其余的都是经过校准的模拟参数，以重现合理的寿命并让习惯和决策发挥作用。",
