    "Mudarte cambia tu residencia y tu moneda local, no tu país de nacimiento. La vida que ya viviste no se borra. La pareja o los hijos pueden quedarse, acompañarte o viajar contigo; cada decisión tiene un coste y una consecuencia.": "搬家会改变您的居住地和当地货币，而不是您的出生国。你已经过的生活并没有被抹去。您的伴侣或孩子可以留下来、陪伴您或与您一起旅行；每个决定都有成本和后果。",
