    "Nacimiento hoy": "今天出生",
    "Nació una persona pequeña que cambió el tamaño de todo. Aprendiste a dormir por turnos y a querer sin condiciones.": "一个小人物诞生了，他改变了一切的大小。你学会了轮流睡觉和无条件地爱。",
    "Naciones Unidas, World Population Prospects 2024": "联合国，2024 年世界人口前景",
    "Nadie quiere hablar de la dependencia hasta que ya está en la mesa. Hoy puedes decidir cómo repartir tiempo, dinero y responsabilidad.": "在依赖问题摆上桌面之前，没有人愿意谈论它。今天你可以决定如何分配时间、金钱和责任。",
    "Nadie quiere volver a entrar en casa. La calle se convierte en refugio y en lugar de encuentro. La decisión inmediata convive con una pregunta más larga: qué hacer con lo que queda.": "没有人愿意回到房子里。街道成为避难所和聚会场所。眼前的决定与一个更长的问题并存：如何处理剩下的东西。",
    "Nadie verá esta elección hasta que el turno se resuelva para ambos jugadores.": "在双方玩家的回合都解决之前，没有人会看到这一选择。",
    "Nadie volvió a mencionarlo. Durante años conviviste con pequeñas molestias que aprendiste a ignorar.": "没有人再提这件事了。多年来，你一直生活在一些小烦恼中，但你学会了忽略它们。",
