    "Nueva revancha creada con la misma configuración.": "使用相同配置创建新的复赛。",
    "Nuevas terapias retrasan algunas enfermedades asociadas a la edad. La vejez se vuelve más larga y también más cara.": "新疗法可以延缓一些与年龄相关的疾病。老年变得更长，也更昂贵。",
    "Nuevo duelo": "新的对决",
    "Nuevo negocio": "新业务",
    "Nunca es tarde para aprender algo nuevo, pero el tiempo y el dinero no son infinitos.": "学习新东西永远不会太晚，但时间和金钱不是无限的。",
    "Obra pequeña, menos coste y un espacio que se siente tuyo.": "工作量小，成本低，空间感觉就像您的。",
    "Observar hasta entender quién es quién": "观察直到你明白谁是谁",
    "Observar las sombras de la pared": "观察墙上的影子",
    "Obtener caja ahora a cambio de comisiones y deuda explícita.": "立即获取现金以换取佣金和显性债务。",
    "Obtuvo una visa cualificada": "获得合格签证",
