    "Pedir ayuda": "求人",
    "Pedir ayuda a la familia": "向家人寻求帮助",
    "Pedir ayuda a tiempo es una decisión de salud, no una señal de debilidad.": "及时寻求帮助是一项健康决定，而不是软弱的表现。",
    "Pedir ayuda sin convertirla en una deuda eterna. Cuesta orgullo y cambia la relación.": "寻求帮助，不要把它变成永远的债务。这会损失骄傲并改变关系。",
