    "Pedir una pausa académica desde tus acciones manuales y reconstruir una reserva.": "请求从你的手动操作中获得学术休息并重建储备。",
    "Pedir una prórroga y seguir operando": "请求延期并继续运营",
    "Pedir una segunda opinión y discutir el tratamiento sin aceptar la primera respuesta.": "寻求第二意见并讨论治疗方法，但不接受第一个答案。",
    "Pedir una transición gradual": "要求逐步过渡",
    "Pedirles un préstamo": "向他们请求贷款",
    "Pediste ayuda a una red local. No te sacó de la deuda, pero te dio comida, asesoría y personas con las que dejar de sentir que el problema era una vergüenza privada.": "您向本地网络寻求帮助。它并没有让你摆脱债务，但它给了你食物、建议和人们，让你不再觉得这个问题是个人的耻辱。",
    "Pediste presupuestos y mantuviste la reserva. El mantenimiento pendiente continúa y tendrás que volver a decidir.": "您询问报价并保留预订。待处理的维护仍在继续，您将不得不重新做出决定。",
    "Pediste tiempo. La otra persona esperó sin presión y tú pudiste escuchar lo que querías de verdad.": "你要求时间。对方毫无压力地等待，你能够听到你真正想要的。",
    "Pediste una reducción de jornada. El sueldo bajó y el cuerpo empezó a responder. No era la vida que habías planeado, pero era una que podías sostener.": "您要求减少工作时间。工资下降了，身体开始做出反应。这不是你计划的生活，但却是你可以维持的生活。",
    "Pediste una revisión comercial antes de comprometer el capital. Conservaste la posibilidad de exportar después con mejores preguntas.": "您在投入资金之前要求进行业务审查。您保留了稍后导出更好问题的可能性。",
    "PEN · sol": "笔·太阳",
    "Pensar en lo que dejas": "想想你留下了什么",
