    "Pensaste en irte de tu ciudad. La idea te duró todo el viaje de vuelta.": "你想过离开你的城市。这个想法贯穿了整个回来的旅程。",
    "Pensaste en una decisión que no tomaste y en la persona que podrías haber sido.": "你思考了一个你没有做出的决定以及你本来可以成为的人。",
