    "pérdidas registradas.": "记录的损失。",
    "Perdiste lo invertido. No fue catastrófico, pero escoció.": "你失去了你投资的东西。这不是灾难性的，但令人刺痛。",
    "Perdiste un juguete y lo buscaste durante días. Apareció donde nadie miraba.": "您丢失了一个玩具并寻找了好几天。他出现在没人注意的地方。",
    "Perdiste una piedra que para ti era un tesoro. Alguien se sentó contigo a buscarla hasta que apareció detrás de un mueble. Nunca olvidaste que se quedó.": "你失去了一块对你来说是宝藏的石头。有人坐在你旁边寻找她，直到她出现在一件家具后面。你永远不会忘记他留下来。",
    "Persistencia PostgreSQL conectada mediante Prisma.": "使用 Prisma 连接 PostgreSQL 持久性。",
