    "Pintaste una pared y cambiaste una lámpara. No era la casa que querías, pero dejó de ser la casa que te agotaba.": "你粉刷了一堵墙，换了一盏灯。这不是你想要的房子，但不再是让你疲惫不堪的房子。",
    "Pintaste, arreglaste y cambiaste una ventana. La casa no cambió de dueño, pero sí de sensación.": "您粉刷、修理并更换了窗户。房子的所有权没有改变，但它确实改变了它的感觉。",
