    "Podías pagar a una persona, negociar con los proveedores o pedir un préstamo. Cada opción salvaba una parte del negocio y sacrificaba otra.": "您可以向某人付款、与供应商谈判或申请贷款。每一种选择都挽救了部分业务，同时牺牲了另一部分业务。",
