    "Poner límites al cuidado no equivale a abandonar a la familia.": "对护理设置限制并不等于放弃家庭。",
    "Poner límites claros y proponer un reparto explícito de tiempos y cuidados.": "设定明确的限制并提出明确的时间和护理分配。",
    "Poner límites y hablar con tu responsable": "设定限制并与您的经理交谈",
    "Poner sobre la mesa dónde queréis vivir, cómo repartiréis tiempo y dinero y qué no estáis dispuestos a sacrificar. Sin fecha de boda.": "把你想住在哪里、你将如何分配时间和金钱以及你不愿意牺牲什么摆在桌面上。没有结婚日期。",
    "Poner un límite": "设定一个限制",
