    "Pospusiste el acuerdo y trabajaste con tu cartera actual. El catálogo siguió bajo tu control.": "您推迟了交易并使用当前的投资组合。目录仍然在您的控制之下。",
    "Pospusiste la matrícula y buscaste una base de ingresos. La oportunidad de estudiar siguió abierta.": "你推迟了学费并寻找收入基础。学习的机会仍然开放。",
