    "Preferiste mejorar la rotación local antes de inmovilizar capital en un envío internacional.": "在将资金投入国际运输之前，您更愿意提高本地营业额。",
    "Preguntar por qué se perdió": "询问为何丢失",
    "Preguntar y no interrumpir. Una conversación a la semana.": "询问并且不要打断。每周一次谈话。",
    "Preguntar, buscar y pedir papeles. Perderás la oportunidad si es buena.": "询问、搜索和索取论文。如果机会好的话，你就会失去机会。",
    "Preguntaste por qué el cielo cambiaba de color al caer la tarde.": "你问为什么黄昏时天空会变色。",
    "Preguntaste por qué el cielo cambiaba de color. La primera respuesta no te convenció y seguiste preguntando hasta que un adulto se sentó a mirarlo contigo. Aprendiste que una pregunta también puede ser una forma de compañía.": "你问为什么天空变色了。第一个答案并没有让你信服，你继续问，直到一个成年人坐下来和你一起观看。您了解到问题也可以是陪伴的一种形式。",
    "Preguntaste por qué las cosas eran como eran y nadie tuvo una respuesta completa.": "你问为什么事情是这样的，但没有人给出完整的答案。",
    "Prepara antes la candidatura académica (conocimiento 65)": "提前准备好你的学术候选资格（知识 65）",
    "Prepara un cambio de trabajo": "为工作变动做好准备",
    "Prepara una migración futura": "为未来的迁移做好准备",
    "Preparando el primer pedido. Los márgenes, fletes y cambios se simulan; no son cotizaciones comerciales.": "准备第一笔订单。模拟保证金、运费和汇率；它们不是商业报价。",
    "Preparando las vidas…": "准备生活……",
    "Preparar acceso y presupuesto": "准备访问权限和预算",
    "Preparar clientes, muestras y una ruta marítima. Pedidos, impagos, control de calidad, divisas y fletes afectan al resultado anual. No incluye una mudanza.": "准备客户、样品和航线。订单、未付款、质量控制、货币和运费都会影响年度业绩。不包括移动。",
    "Preparar documentación y solicitar una resolución": "准备文件并请求解决方案",
