    "Preparar una candidatura: el resultado depende de preparación y recursos. Puede reducir a la mitad las cuotas restantes; no paga la vida cotidiana.": "准备候选人：结果取决于准备和资源。您可以将剩余分期付款减少一半；它不支付日常生活费用。",
    "Preparar una carrera tecnológica": "准备技术职业",
    "Preparar una salida sin quemar el puente actual.": "准备一个出口而不烧毁当前的桥梁。",
    "Preparar una separación y proteger las obligaciones familiares": "为分居做好准备并保护家庭义务",
    "Preparaste el acceso a Bologna y organizaste las cuotas de informática. Tendrás que sostener tres años de estudio, gastos y esfuerzo.": "您已准备好进入博洛尼亚并安排了 IT 费用。你必须维持三年的学习、费用和努力。",
    "Preparaste ingresos, deudas y documentación de los bienes. La revisión quedó para una fase posterior.": "您准备了收入、债务和资产文件。审查留到稍后阶段进行。",
    "Preparaste inspección y una cartera más diversa. Aumentaron los costes de control, pero bajaron dos riesgos concretos.": "您准备了检查和更多样化的投资组合。控制成本增加，但两个特定风险减少。",
    "Preparaste tu comercio para la actividad internacional: proveedores, producto y documentación. Ahora puedes evaluar una ruta, sin que exista aún un envío comprometido.": "您为您的企业开展国际活动做好了准备：供应商、产品和文件。现在，您可以在尚未承诺发货的情况下评估路线。",
    "Presentar una candidatura de ayuda": "提交帮助申请",
    "Presentaste la acreditación a empleadores locales y mantuviste tu red de apoyo.": "您向当地雇主介绍了认证并维护了您的支持网络。",
    "Presentaste una denuncia. No recuperaste nada, pero alguien más no cayó en la trampa.": "您已提出投诉。你没有得到任何回报，但其他人并没有上当。",
    "Preservar activos, usando saldo y crédito disponible. Puede dejarte con una deuda difícil de sostener.": "使用可用余额和信用来保护资产。它可能会给您留下难以承担的债务。",
