    "Prestar, regalar y decir que no son decisiones distintas. El juego registra el dinero y la deuda; no decide por ti qué es la lealtad.": "借出、给予和拒绝是不同的决定。游戏追踪金钱和债务；它并不能决定什么是忠诚。",
