    "Presupuesto de simulación en dólares internacionales (PPP); no es una oferta real de viaje, visado ni matrícula.": "以国际美元计算的模拟预算（PPP）；它不是真正的旅行、签证或注册要约。",
    "Presupuesto estimado del país: 4 % del PIB por persona al año durante esta etapa, con cuotas hasta los 23 años. No asegura admisión ni empleo.": "国家预估预算：此阶段每人每年GDP的4%，配额至23岁。不保证入学或就业。",
    "Prima anual pagada ahora: 0,6 % del PIB por persona. Cobertura de juego del 80 % del PIB por persona para familiares vivos si falleces durante los próximos doce meses. No aumenta tu saldo ni tu puntuación al morir; no es una póliza real.": "现在缴纳的年度保费：每人GDP的0.6%。如果您在未来 12 个月内去世，则为在世家庭成员提供每人 GDP 的 80% 的赌博保险。当你死亡时，你的余额或分数不会增加；这不是真正的政策。",
