    "Prioriza tu trayectoria, tus ingresos y tu experiencia profesional.": "优先考虑你的职业、收入和专业经验。",
    "Priorizar amistades, proyectos y tiempo propio.": "优先考虑友谊、项目和自己的时间。",
    "Priorizar el trabajo": "确定工作的优先顺序",
    "Priorizar ingresos ahora, dejando abierta la formación posterior.": "现在优先考虑收入，留出以后的培训机会。",
    "Priorizar la escuela": "优先考虑学校",
    "Priorizar no es elegir la opción perfecta; es aceptar qué queda fuera esta vez.": "优先排序并不是选择完美的选项，而是选择最合适的选项。它正在接受这次被遗漏的东西。",
    "Priorizar terminar lo que ya tienes entre manos antes de añadir otra exigencia.": "在添加另一个需求之前，优先完成手头已有的任务。",
    "Priorizaste la reparación urgente y conservaste parte de la reserva. Quedan trabajos, pero el estado mejoró.": "您优先考虑紧急维修并保留了部分储备。虽然还有工作岗位，但情况有所改善。",
    "Priorizaste un empleo para sostener la vida cotidiana. Podías solicitar una pausa académica y retomar después con una reserva.": "您优先考虑工作来维持日常生活。您可以请求学术休息，并在预约后稍后返回。",
    "Privacidad y responsabilidad total. La fianza y el alquiler pesan.": "隐私和全部责任。押金和房租很重要。",
