    "Probar una muestra del proveedor alternativo": "测试替代供应商的样品",
    "Probar, equivocarte y entender cómo encajan.": "尝试、犯错误并了解它们如何组合在一起。",
    "Probaste tratamientos que no siempre entendías. Hubo días de esperanza y días en los que solo querías dormir.": "您尝试了一些您并不总是理解的治疗方法。有充满希望的日子，也有只想睡觉的日子。",
