    "Quedarte el dinero": "保留钱",
    "Quedarte en casa y dibujar": "呆在家里画画",
    "Quedarte en tu puesto": "留在你的岗位上",
    "Quedarte y ahorrar": "留下来并节省",
    "Quedarte y construir aquí": "留下来并在这里建造",
    "Quedarte y mejorar el perfil": "留下来并改善您的个人资料",
    "Quedarte y preparar la salida": "留下来并准备离开",
    "Quedarte y preparar una migración mejor": "留下来并为更好的迁移做好准备",
    "Quedarte y reconstruir aquí": "留在这里并重建",
    "Quedaste con alguien que hacía tiempo que no veías. La conversación retomó donde se había quedado.": "你遇到了一个许久未见的人。谈话从中断的地方继续下去。",
    "Quedasteis fuera de la oficina y hablasteis de lo que cada uno esperaba. La relación empezó con una regla sencilla: el trabajo no sería el lugar para resolverla.": "你们呆在办公室外面，谈论了你们每个人的期望。这种关系始于一个简单的规则：工作不是解决问题的地方。",
    "Querer ver cómo se prepara todo": "想看看一切准备得如何",
    "Quiebra personal: condonación parcial": "个人破产：部分宽恕",
    "Quienes te acompañan": "谁陪你",
    "Rampas, barandillas y una ducha sin bordes.": "坡道、栏杆和无边淋浴间。",
    "Rasgos y consecuencias acumuladas": "特征和累积后果",
    "Reagrupó a su familia": "他让家人团聚",
