    "Reanudar ahora": "立即恢复",
    "Reanudar la vida »": "恢复生活»",
    "Reanudar partida": "继续游戏",
    "Recargo por expediente ignorado": "忽略文件的附加费",
    "Recepción y atención al público": "公众的接待和关注",
    "Rechazar el acuerdo sin cerrar futuras colaboraciones; no recibes capital imaginario de un socio.": "拒绝协议而不终止未来的合作；您不会从合作伙伴那里收到虚拟资本。",
    "Rechazar el contrato y atender la cartera actual": "拒绝合同并关注当前的投资组合",
    "Rechazar el riesgo y elegir una reconstrucción lenta pero verificable.": "拒绝风险并选择缓慢但可验证的重建。",
    "Rechazar la oferta": "拒绝报价",
    "Rechazar la oferta y seguir buscando": "拒绝报价并继续搜索",
    "Rechazar la oferta y seguir pequeño": "拒绝报价并保持规模较小",
    "Rechazar la presentación": "拒绝提交",
    "Rechazar lo arriesgado y buscar una vía más lenta pero segura.": "拒绝冒险，寻找一条更慢但更安全的道路。",
    "Rechazaste el acuerdo por ahora y conservaste la autonomía de tu empresa. El crecimiento tendría otro ritmo.": "你们暂时拒绝了该协议并保留了你们公司的自主权。增长速度将会有所不同。",
    "Rechazaste el contrato. La empresa siguió siendo pequeña y controlable, con clientes que conocías por su nombre.": "你拒绝了合同。该公司仍然规模较小且可控，客户的名字你都知道。",
    "Rechazaste la oferta. El negocio siguió siendo tuyo, con sus noches largas y sus pequeñas victorias.": "你拒绝了这个提议。尽管漫长的夜晚和小小的胜利，生意仍然是你的。",
    "Recibió ayuda económica familiar": "接受家庭经济援助",
    "Recibió la herencia familiar": "获得了家族遗产",
    "Recibiste atención y seguiste un plan de cuidados. Tu salud mejoró un poco.": "您接受了护理并遵循了护理计划。你的健康状况有所改善。",
    "Recibiste más silencios que respuestas. Seguiste formándote mientras la búsqueda se alargaba.": "你收到的沉默多于答案。随着搜索的进行，你继续训练。",
    "Recibiste tus primeros cuidados. Tu familia aprendía tus gestos, tu llanto y tus horarios.": "您接受了第一次护理。你的家人了解了你的手势、你的哭泣和你的日程安排。",
    "Recién nacido": "新生",
    "Reconocer el gesto sin comprometerte con algo que no buscas.": "识别手势，但不做任何你不想要的事情。",
    "Reconocer que el deseo no encaja con tu tiempo y tu dinero.": "认识到这种愿望与你的时间和金钱不相符。",
    "Reconocer que no tienes margen y decirlo sin culpa.": "认识到你没有余地，并且毫无愧疚地说出来。",
