    "Reduce un riesgo concreto del próximo pedido; exige preparación y algunos controles añaden costes a cada envío. No garantiza beneficios.": "降低下一个订单的特定风险；需要准备，并且某些控制措施会增加每次装运的成本。不保证福利。",
