    "Reducir temporalmente el menú": "暂时减少菜单",
    "Reduciste demasiado una línea que sí atraía clientes. Recuperaste caja, pero tuviste que rehacer parte del catálogo.": "你减少了太多吸引顾客的队伍。您收回了现金，但必须重做部分目录。",
    "Redujiste actividad y plantilla para sobrevivir. El negocio quedó más pequeño y más frágil, pero siguió existiendo.": "为了生存，您减少了活动和人员。该业务变得更小、更脆弱，但它仍然存在。",
    "Redujiste compromisos: pausaste la formación activa y dejaste el empleo externo para dirigir tu empresa.": "您减少了承诺：您暂停了积极的培训并离开外部工作来经营您的公司。",
    "Redujiste el segmento y los costes. No fue una retirada heroica: fue evitar perder dinero en una guerra que no podías ganar.": "您减少了细分市场和成本。这不是一次英勇的撤退：这是为了避免在一场无法获胜的战争中损失金钱。",
    "Redujiste la jornada y descubriste que todavía disfrutabas enseñando lo que sabías. El tiempo libre se volvió más valioso.": "你减少了时间，发现你仍然喜欢教授你所知道的东西。空闲时间变得更有价值。",
    "Redujiste temporalmente la agenda. Hubo menos facturación, pero el equipo pudo trabajar con recursos suficientes.": "你暂时减少了议程。账单减少了，但团队能够利用足够的资源开展工作。",
