    "Reuniste a la familia y explicaste tus decisiones. No todos estuvieron de acuerdo, pero nadie tuvo que adivinar qué querías después.": "你召集了家人并解释了你的决定。并非所有人都同意，但没有人必须猜测你下一步想要什么。",
