    "Salud, dinero y vínculos influyen en estas cifras. No son un diagnóstico: son una lectura del estado emocional que arrastra la vida simulada.": "健康、金钱和关系都会影响这些数字。它们不是诊断：它们是对模拟生活所持续的情绪状态的解读。",
    "Salvó un caso difícil": "挽救了一个疑难案件",
    "Sanción fiscal del negocio": "营业税罚款",
    "Sanción grave por fraude fiscal": "税务欺诈将受到严厉处罚",
    "Sanción por brecha de datos": "数据泄露处罚",
    "Satisfacción": "满意",
    "Satisfacción vital": "生活满意度",
    "script, style, noscript, code, pre, textarea, [data-no-i18n], .no-i18n": "脚本、样式、noscript、代码、pre、textarea、[data-no-i18n]、.no-i18n",
    "Se amplía la cobertura de algunas consultas y se recortan otras. Las listas de espera se mueven sin que nadie sepa muy bien hacia dónde.": "一些咨询的范围扩大了，另一些则缩小了。等候名单不断变化，但没有人清楚地知道在哪里。",
    "Se añade una matrícula anual equivalente al 6 % del PIB por persona del país, repartida en doce recibos hasta los 18 años. El dinero no garantiza resultados.": "每年还要加上相当于该国每人GDP 6%的注册费，分成十二份收据直至18岁。金钱并不能保证结果。",
    "Se apagaron las luces": "灯灭了",
    "Se cobró el pedido.": "该订单已收费。",
    "Se creará al empezar": "它将在开始时创建",
    "Se mudó hace poco": "他最近搬家了",
    "Se pactó la salida y la vivienda quedó vacante. Recuperaste una parte de las rentas pendientes, pero ahora tendrás meses sin ingresos hasta encontrar otro contrato.": "离开被同意了，房子就空了。您收回了部分未付租金，但现在您将有几个月没有收入，直到您找到另一份合同。",
    "Se trabaja mucho y se habla poco de dinero. La familia conoce el valor de cada factura y la importancia de no deber favores.": "我们工作很多，很少谈论金钱。家人知道每张账单的价值以及不欠人情的重要性。",
    "Se usará al abrir «Nueva vida» o «Duelo para dos». Puedes cambiarla en cada partida antes de comenzar.": "开启“新生活”或“两人决斗”时会使用。您可以在开始之前在每个游戏中更改它。",
    "Secuela de una enfermedad grave": "大病后遗症",
    "Secuelas de accidente de tráfico": "交通事故后的后果",
    "Secuelas de una enfermedad tratada tarde": "疾病治疗晚的后遗症",
    "Seguir adelante sin cambiar nada": "不改变任何事情，继续前进",
    "Seguir al mando": "保持控制",
    "Seguir alquilando": "继续出租",
    "Seguir aprendiendo sin examen": "无需考试即可继续学习",
    "Seguir como estáis": "继续原样",
    "Seguir como hasta ahora": "像以前一样继续",
    "Seguir como puedes": "尽你所能继续",
    "Seguir con la nómina": "继续工资单",
    "Seguir con tu rutina": "继续你的日常活动",
    "Seguir conociéndoos, con sinceridad": "继续真诚地认识你",
    "Seguir el circuito público": "遵循公共线路",
    "Seguir el protocolo y consultar": "遵循协议并咨询",
    "Seguir el tratamiento público": "遵循公共治疗",
    "Seguir en casa de la familia": "留在家人家里",
    "Seguir en casa te da margen económico y menos intimidad. Irte te da independencia y una factura que no perdona. No hay una salida limpia.": "呆在家里会给你带来经济利润和更少的隐私。离开会给你带来独立和无情的账单。没有干净的出口。",
    "Seguir independiente y reforzar la reserva": "保持独立，加强储备",
    "Seguir las clases desde tu habitación": "在您的房间上课",
    "Seguir pagando como hasta ahora y esperar tiempos mejores.": "继续像以前一样付款并等待更好的时机。",
    "Seguir probando hasta hacerlo sonar": "继续测试直到发出声音",
    "Seguir trabajando": "继续工作",
    "Seguiste como si nada. El cuerpo no envió una factura inmediata, pero dejó una señal que ya no podías ignorar.": "你继续说着，好像什么也没发生过一样。该机构没有立即发出账单，但它留下了一个你不能再忽视的信号。",
    "Seguiste en casa. No fue gratis: hubo tensión y preguntas. Pero tu ahorro creció y la salida futura tenía más base.": "你呆在家里。它不是免费的：存在紧张和问题。但你的储蓄增加了，未来的收入也有了更多的基础。",
    "Seguiste funcionando. La vida no se detuvo, pero el cansancio se acumuló en el cuerpo y en las relaciones que más te importaban.": "你继续奔跑。生活并没有停止，但疲劳在你的身体和对你最重要的关系中累积。",
    "Seguiste levantándote temprano. La rutina te sostuvo y también te impidió escuchar el cansancio.": "你一直很早起床。这种习惯可以维持你的健康，也可以防止你听力疲劳。",
    "Seguiste mirando el techo y la pantalla. El cansancio se hizo costumbre, que no es lo mismo que descansar.": "你继续看着天花板和屏幕。疲劳成为一种习惯，这与休息不一样。",
    "Seguiste pagando sin cambiar nada. La deuda no empeoró, pero el margen siguió siendo estrecho y la preocupación se quedó otro año.": "您继续付款，没有任何改变。债务并没有恶化，但利润率仍然很窄，人们的担忧又持续了一年。",
    "Seguisteis coincidiendo en las actividades del barrio. La confianza creció sin necesidad de una cita.": "你们在邻里活动中继续保持一致。无需预约即可增强信任。",
    "Seguisteis compartiendo apuntes y alguna comida. La amistad encontró su sitio sin necesidad de nombrarlo todo.": "你继续分享笔记和一些食物。友谊不需要说出一切，就找到了它的位置。",
    "Seguisteis corrigiendo los errores del otro. La amistad era suficiente y no necesitaba una prueba de amor.": "你们不断地纠正彼此的错误。友情就足够了，不需要爱情的证明。",
    "Seguisteis hablando de madrugada. La amistad cruzó fronteras sin pedir una mudanza ni una promesa que no podíais sostener.": "黎明时分你继续说话。友谊跨越国界，无需采取行动，也无需做出无法兑现的承诺。",
    "Seguisteis pasando apuntes y cuidando el silencio. No era una historia de amor, pero era una forma de no estar solo.": "你继续传递纸条并保持沉默。这不是一个爱情故事，但它是一种不孤单的方式。",
    "Seguisteis siendo aliados en el trabajo. La amistad no necesitaba una etiqueta para sostener las mañanas difíciles.": "你们在工作中继续是盟友。友谊不需要标签来维持艰难的早晨。",
    "Segundo comienzo": "第二次开始",
    "Segundo local fallido": "第二个失败位置",
    "Seguridad y rutina. Menos sorpresas y menos crecimiento.": "安全和常规。更少的惊喜和更少的增长。",
