    "Sentarte a escucharle": "坐下来听他说话",
    "Sentarte junto a otro niño": "坐在另一个孩子旁边",
    "Sentiste que el año pasaba más deprisa de lo que querías.": "你感觉这一年过得比你想象的要快。",
    "Señalar cada detalle para que te lo expliquen": "指出每个细节，以便他们向您解释",
    "Separación y acuerdos": "分居和协议",
    "Separar lo esencial, recortar lo prescindible y hacer un plan realista.": "分离必需品，剔除可有可无，制定切合实际的计划。",
    "Separaste facturas por antigüedad, renegociaste pagos y estabilizaste la tesorería. La clínica pudo mantener atención y suministros.": "您按账龄分开发票，重新协商付款并稳定了财务状况。诊所能够维持护理和供应。",
    "Separaste los hogares. La compensación patrimonial y los acuerdos de cuidado se decidirán en las próximas preguntas; ya no se suman los ingresos de tu expareja.": "你们分居了。财产补偿和照顾安排将在接下来的问题中决定；您前伴侣的收入不再累加。",
    "Ser adulto y disponer de un colchón económico.": "成为一个成年人并拥有一个负担得起的床垫。",
    "Ser claro/a sobre el matrimonio y escuchar si vuestra relación puede continuar con esa diferencia.": "明确婚姻关系，并倾听你们的关系是否可以在这种差异下继续下去。",
    "Ser claro/a sobre lo que quieres, aunque eso pueda cambiar la relación.": "明确你想要什么，即使这可能会改变关系。",
    "Serie": "系列",
