    "Sesenta y cinco años. Pensaste en todo lo que has vivido y en cómo quieres pasar los años que vienen.": "六十五岁。你想过你所经历的一切，以及你想如何度过未来的岁月。",
    "Sesión no válida.": "无效会话。",
