    "SESSION_SECRET es obligatorio en producción.": "生产中需要 SESSION_SECRET。",
    "Si ya no puedes sostener sus cuidados, busca un hogar adecuado para un animal. No produce ingresos; la despedida afecta al bienestar.": "如果您无法再支持他们的照顾，请为动物寻找合适的家。它不产生收入；告别会影响幸福感。",
    "sigue jugando a su ritmo": "继续按照自己的节奏玩",
