    "Solicitaste la revisión con documentación incompleta. El caso siguió abierto y conservó más incertidumbre.": "您请求审查的文件不完整。此案仍然悬而未决，并且仍然更加不确定。",
    "Solicitaste una pausa académica. Dejan de cargarse nuevas cuotas y se detiene el progreso; las facturas anteriores siguen debiéndose.": "您请求学业休息。停止收取新费用，进度停止；以前的发票仍然到期。",
    "Solo después de un compromiso aceptado. Una celebración sencilla, con coste local y consecuencias para el hogar.": "只有在接受承诺之后。一个简单的庆祝活动，当地的成本和对家庭的影响。",
    "Solo el anfitrión puede activar o desactivar el modo automático. Tus decisiones siguen siendo tuyas.": "只有主机可以打开或关闭自动模式。您的决定仍然由您决定。",
    "Solo el anfitrión puede activar o desactivar las decisiones automáticas.": "只有主机可以打开或关闭自动决策。",
