    "Son estimaciones del modelo. La herencia solo se recibe tras el fallecimiento de ambos progenitores y no sustituye a los activos reales de la partida.": "它们是模型估计。遗产只有在父母双亡后才能收到，并且不能取代该物品的实际资产。",
