    "Subconjunto demográfico de demostración para LIFE DUEL. Los valores están redondeados a partir de fuentes públicas y se usan para ponderar nacimientos y calibrar el modelo. No son una réplica exacta de las bases de datos originales.": "生命决斗的演示人口统计子集。值是从公共来源四舍五入的，用于衡量出生率和校准模型。它们不是原始数据库的精确复制品。",
