    "Suspendiste la actividad digital y reconstruiste el acceso. Perdiste ventas de varias semanas, pero el negocio no arrastró una brecha abierta.": "您暂停了数字活动并重建了访问权限。您损失了几周的销售额，但业务并没有出现明显的缺口。",
    "Sustituir el plan por una versión accesible que también te haga bien.": "将计划替换为可访问的版本，这对您也有好处。",
