    "Volviste a abrir con lo justo. Sabías qué errores no querías repetir y a quién no volverías a contratar. El negocio creció más despacio y con más cicatrices.": "你重新打开就足够了。您知道您不想重复哪些错误以及您不会再次雇用谁。业务增长更加缓慢，伤痕也更多。",
    "Volviste a casa más tarde de lo acordado. La conversación fue más larga que el castigo.": "你回家的时间比约定的晚了。谈话的时间比惩罚还要长。",
    "Volviste a las aulas con más cansancio y más claro que antes. La formación no borró el error, pero cambió lo que podías intentar después.": "回到教室的你比以前更疲惫，也更清醒。培训并没有消除错误，但它改变了你接下来可以尝试的事情。",
    "Volviste a mirar una convocatoria de estudios que habías dejado pasar. La edad ya no era el obstáculo que imaginabas; el tiempo y el dinero, sí.": "你又看了一次你错过的学习电话。年龄不再是你想象中的障碍；时间和金钱，是的。",
    "Volviste a ser principiante y descubriste que no te importaba. La experiencia se convirtió en una ventaja inesperada.": "你又变成了一个初学者，却发现你不在乎。这段经历成为了意想不到的优势。",
    "Volviste a tener gente que contaba contigo. Los miércoles se llenaron de nombres y de tareas pequeñas.": "你再一次有了信任你的人。周三充满了名字和小任务。",
    "Volviste a trabajar por cuenta ajena. El sueldo era menor que tus mejores años de empresario, pero la nómina llegaba y podías dormir sin revisar la caja.": "你又回去当雇员了。薪水低于你作为商人最好的年头，但工资单到了，你可以不用检查收银机就睡觉了。",
    "Volviste a un lugar de tu infancia. Te pareció más pequeño de lo que recordabas.": "你回到了小时候的地方。它似乎比你记忆中的要小。",
    "Volviste a un lugar de tu juventud y comprobaste que la memoria lo había hecho más grande.": "你回到了年轻时的地方，发现记忆让它变得更大。",
    "Volviste con más años y menos certezas. La ciudad había cambiado, y tú también. Aun así, reconociste el olor de la calle y supiste que una parte de ti nunca se había ido.": "你带着更多的岁月和更少的确定性回来了。城市变了，你也变了。尽管如此，你还是认出了街上的气味，并且知道你的一部分从未离开过。",
    "Volviste. La familia estaba completa y el proyecto migratorio quedó a medias. A veces reconstruir también es elegir qué no quieres perder.": "你回来了。家庭完整了，移民项目却半途而废。有时候重建也是选择你不想失去的东西。",
