    "Los gastos equivalen al {{x}} % de los ingresos anuales del hogar.": "费用等于家庭年收入的 {{x}} %。",
    "Los mayores empezaron a describirte como una persona de temperamento {{x}}.": "长辈们开始形容你是一个具有{{x}}气质的人。",
    "Mapa del mundo: {{x}} destacado": "世界地图：精选{{x}}",
    "Materiales y transporte escolar · {{x}}": "学校材料和交通 · {{x}}",
    "Modelo de realismo inválido: {{x}}": "无效的现实主义模型：{{x}}",
    "Nacer en {{x}}": "出生于{{x}}",
    "Nació {{x}}, {{x}}. La casa cambió de ritmo con su llegada.": "{{x}}，{{x}} 诞生了。随着他的到来，房子的节奏发生了变化。",
    "Nació {{x}}, {{x}}. La primera vez que le sostuviste, todo pareció detenerse.": "{{x}}，{{x}} 诞生了。当你第一次拥抱他时，一切似乎都停止了。",
    "No hay ocupaciones compatibles para {{x}}/{{x}}/{{x}}.": "{{x}}/{{x}}/{{x}} 没有受支持的职业。",
    "No pudiste completar el traslado a {{x}}. Los trámites no salieron adelante.": "您无法完成到 {{x}} 的迁移。手续没有​​继续进行。",
    "No se pudo leer el conjunto demográfico en {{x}}": "无法读取 {{x}} 中的人口统计数据集",
    "Pagaste {{x}} dólares PPP de {{x}}. El movimiento quedó registrado en la cuenta.": "您支付了 {{x}} PPP 美元 {{x}}。这一变动已记录在账户中。",
    "Pago de hipoteca · {{x}}": "抵押贷款·{{x}}",
    "País de nacimiento: {{x}}. Años vividos: {{x}}.": "出生国家：{{x}}。寿命：{{x}}。",
    "País no disponible en el conjunto demográfico: {{x}}": "人口统计集中不存在的国家/地区：{{x}}",
    "Pañales e higiene · {{x}}": "尿布和卫生·{{x}}",
    "Pasó {{x}} años con una felicidad inferior a 30/100.": "他度过了 {{x}} 年，幸福感低于 30/100。",
    "Patrimonio en discusión: {{x}} PPP · saldo disponible: {{x}} PPP · alimentos previstos: {{x}} PPP/año. Importes simulados, sujetos al resultado del acuerdo.": "正在讨论的资产：{{x}} PPP · 可用余额：{{x}} PPP · 计划食品：{{x}} PPP/年。模拟金额，以协议结果为准。",
    "Pensaste en irte de {{x}}. La idea te duró todo el viaje de vuelta y volvió cada vez que el horizonte parecía demasiado conocido.": "你想过离开{{x}}。这个想法贯穿了整个回来的旅程，每次当地平线看起来太熟悉时，这个想法就会出现。",
    "Pérdidas financiadas de {{x}}": "{{x}} 资助损失",
    "Podrían prestar hasta {{x}} PPP.": "他们最多可以借出 {{x}} PPP。",
    "Preparaste una ruta comercial a {{x}}. Antes del embarque, quedaban por acordar anticipos, inspección y cobertura de transporte.": "您准备了一条通往 {{x}} 的贸易路线。装运前，预付款、检验和运输范围仍有待商定。",
    "Presión patrimonial {{x}} de 100": "资产压力 {{x}} 为 100",
    "Presupuesto individual de juego: billetes {{x}} PPP, documentación {{x}} PPP y estancia de una semana {{x}} PPP. No es una tarifa oficial ni garantiza un visado. La visita no cambia tu residencia.": "个人博彩预算：{{x}} PPP 门票、{{x}} PPP 文件和一周住宿 {{x}} PPP。它不是官方费用，也不保证获得签证。这次访问不会改变您的居住地。",
    "Recibiste un préstamo de {{x}} dólares PPP. El capital y los intereses deben devolverse.": "您收到了 {{x}} PPP 美元的贷款。必须偿还本金和利息。",
    "Reformaste {{x}}. Pagaste conservación sin borrar deudas del inquilino.": "你改革了{{x}}。您支付了维护费，但没有消除租户的债务。",
