    "Se destinaron {{x}} a cancelar la hipoteca.": "{{x}} 用于偿还抵押贷款。",
    "Semilla pública {{x}} · Reglas de puntuación visibles · life-duel": "公开种子{{x}} · 看得见的计分规则 · 生命决斗",
    "Sigue vivo a los {{x}} años. No puedes ver su elección pendiente.": "他还活着 {{x}} 年。你看不到他即将举行的选举。",
